let data = load(); let currentFilter='all';
function load(){try{return JSON.parse(localStorage.getItem('utm-ops-data'))||structuredClone(SEED)}catch{return structuredClone(SEED)}}
function save(){localStorage.setItem('utm-ops-data',JSON.stringify(data));renderAll()}
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const statusLabel={pending:'CHỜ DUYỆT',approved:'ĐÃ DUYỆT',simulating:'MÔ PHỎNG',rejected:'TỪ CHỐI',ready:'SẴN SÀNG',flying:'ĐANG BAY',warning:'CẢNH BÁO',maintenance:'BẢO TRÌ'};
function now(){return new Intl.DateTimeFormat('vi-VN',{dateStyle:'short',timeStyle:'medium',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date())}
function log(type,message,ref,actor='Khánh Nguyễn'){data.logs.unshift({time:now(),type,message,actor,ref})}
function toast(title,detail){$('#toast b').textContent=title;$('#toast small').textContent=detail;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function renderAll(){renderStats();renderQueue();renderPlans();renderFleet();renderAlerts();renderLogs();renderActivity();fillSelects()}
function renderStats(){const pending=data.plans.filter(p=>p.status==='pending').length,alerts=data.alerts.filter(a=>a.open).length,ready=data.uavs.filter(u=>u.status==='ready').length,active=data.uavs.filter(u=>u.status==='flying'||u.status==='warning').length;$('#pendingCount').textContent=String(pending).padStart(2,'0');$('#pendingBadge').textContent=pending;$('#openAlertCount').textContent=String(alerts).padStart(2,'0');$('#alertBadge').textContent=alerts;$('#readyCount').innerHTML=`${String(ready).padStart(2,'0')}<span>/ ${data.uavs.length}</span>`;$('#activeCount').textContent=String(active).padStart(2,'0')}
function renderQueue(){const list=data.plans.filter(p=>p.status==='pending').slice(0,3);$('#approvalQueue').innerHTML=list.length?list.map(p=>`<div class="queue-item"><span class="queue-code">${p.id.slice(-2)}</span><div><h3>${p.mission}</h3><p>${p.uav} · ${p.route}</p></div><time>${p.time}</time><div class="queue-actions"><button class="approve" data-approve="${p.id}">Phê duyệt</button><button class="reject" data-reject="${p.id}">Từ chối</button></div></div>`).join(''):'<div class="queue-item"><div><h3>Đã xử lý toàn bộ</h3><p>Không còn kế hoạch chờ duyệt.</p></div></div>'}
function renderPlans(){const q=($('#planSearch')?.value||'').toLowerCase();const rows=data.plans.filter(p=>(currentFilter==='all'||p.status===currentFilter)&&Object.values(p).join(' ').toLowerCase().includes(q));$('#plansTable').innerHTML=`<div class="table-row table-header"><span>MÃ KẾ HOẠCH</span><span>NHIỆM VỤ</span><span>UAV</span><span>KHỞI HÀNH</span><span>ĐỘ CAO / TUYẾN</span><span>TRẠNG THÁI</span><span>THAO TÁC</span></div>`+rows.map(p=>`<div class="table-row"><span class="mono">${p.id}</span><span><strong>${p.mission}</strong><small>${p.operator}</small></span><strong>${p.uav}</strong><span><strong>${p.time}</strong><small>${p.date}</small></span><span><strong>${p.altitude} m</strong><small>${p.route}</small></span><span class="status-pill ${p.status}">${statusLabel[p.status]}</span><div class="row-actions">${p.status==='pending'?`<button class="approve" data-approve="${p.id}">Duyệt</button>`:''}<button class="detail-btn">Chi tiết</button></div></div>`).join('')}
function renderFleet(){$('#fleetGrid').innerHTML=data.uavs.map(u=>`<article class="panel uav-card"><div class="uav-top"><span class="uav-icon">⌁</span><span class="status-pill ${u.status}">${statusLabel[u.status]}</span></div><h3>${u.id}</h3><p>${u.model} · ${u.serial}</p><div class="uav-meta"><span>PIN<b>${u.battery}%</b></span><span>GIỜ BAY<b>${u.flight}h</b></span><span>BẢO TRÌ<b>${u.maint}</b></span></div><div class="battery"><i style="width:${u.battery}%;background:${u.battery<40?'var(--red)':'var(--green)'}"></i></div></article>`).join('')}
function renderAlerts(){$('#alertFeed').innerHTML=data.alerts.map(a=>`<article class="panel alert-card ${a.level}"><span class="alert-symbol">△</span><div><h3>${a.title}</h3><p>${a.detail}</p><small>${a.id} · ${a.uav} · ${a.time}</small></div>${a.open?`<button class="resolve-btn" data-resolve="${a.id}">Đã xử lý</button>`:`<span class="status-pill">ĐÃ ĐÓNG</span>`}</article>`).join('')}
function renderLogs(){$('#logsTable').innerHTML=`<div class="table-row table-header"><span>THỜI GIAN</span><span>SỰ KIỆN</span><span>NỘI DUNG</span><span>TÁC NHÂN</span><span>THAM CHIẾU</span></div>`+data.logs.map(l=>`<div class="table-row"><span class="mono">${l.time}</span><span>${l.type}</span><strong>${l.message}</strong><span>${l.actor}</span><span class="mono">${l.ref}</span></div>`).join('')}
function renderActivity(){$('#activityTable').innerHTML=data.logs.slice(0,5).map(l=>`<div class="activity-row"><time>${l.time.split(' ').pop()}</time><span class="event"><i>${l.type==='ALERT'?'!':'✓'}</i><b>${l.message}</b></span><span>${l.actor}</span><span class="mono">${l.ref}</span><span class="status ${l.type==='ALERT'?'warn':''}">${l.type}</span></div>`).join('')}
function fillSelects(){const opts=data.uavs.map(u=>`<option value="${u.id}">${u.id} · ${u.model}</option>`).join('');$('#commandUav').innerHTML=opts;$('#planUav').innerHTML=data.uavs.filter(u=>u.status!=='maintenance').map(u=>`<option value="${u.id}">${u.id} · ${u.model}</option>`).join('')}
function go(page){$$('.page').forEach(x=>x.classList.toggle('active',x.id===page));$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('#pageCrumb').textContent=$(`.nav-item[data-page="${page}"]`)?.textContent.trim()||'Tổng quan';$('#sidebar').classList.remove('open');scrollTo(0,0)}
function openModal(){$('#modalBackdrop').classList.add('open');const d=new Date(Date.now()+3600000);d.setMinutes(Math.ceil(d.getMinutes()/5)*5);$('#planForm [name=departure]').value=d.toISOString().slice(0,16)}
function closeModal(){$('#modalBackdrop').classList.remove('open')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)go(b.dataset.page);if(b.dataset.goto)go(b.dataset.goto);if(b.dataset.approve){const p=data.plans.find(x=>x.id===b.dataset.approve);p.status='simulating';log('APPROVE',`Kế hoạch ${p.id} đã duyệt và chuyển sang mô phỏng`,p.id);save();toast('Đã phê duyệt',`${p.id} đang được chuyển sang mô phỏng.`)}if(b.dataset.reject){const p=data.plans.find(x=>x.id===b.dataset.reject);p.status='rejected';log('REJECT',`Kế hoạch ${p.id} bị từ chối`,p.id);save();toast('Đã từ chối',`Đã cập nhật trạng thái ${p.id}.`)}if(b.dataset.resolve){const a=data.alerts.find(x=>x.id===b.dataset.resolve);a.open=false;log('RESOLVE',`Đã xử lý cảnh báo ${a.id}`,a.id);save();toast('Cảnh báo đã đóng',a.id)}})
$$('.close-modal').forEach(b=>b.onclick=closeModal);$('#modalBackdrop').onclick=e=>{if(e.target===$('#modalBackdrop'))closeModal()};$('#newPlanBtn').onclick=openModal;$('.page-new-plan').onclick=openModal;$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');
$('#planForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d=new Date(f.get('departure')),id=`FP-${String(Date.now()).slice(-8)}`;data.plans.unshift({id,mission:f.get('mission'),uav:f.get('uav'),operator:f.get('operator'),time:d.toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'}),date:d.toLocaleDateString('vi-VN'),route:f.get('route'),altitude:Number(f.get('altitude')),status:'pending'});log('CREATE',`Tạo kế hoạch ${id} và gửi phê duyệt`,id);save();e.target.reset();closeModal();go('plans');toast('Đã tạo kế hoạch',`${id} đang chờ phê duyệt.`)};
$('#planSearch').oninput=renderPlans;$('#planFilters').onclick=e=>{const b=e.target.closest('button');if(!b)return;currentFilter=b.dataset.filter;$$('#planFilters button').forEach(x=>x.classList.toggle('active',x===b));renderPlans()};
$('#sendCommandBtn').onclick=()=>{const u=$('#commandUav').value,c=$('#commandType').value,n=$('#commandNote').value.trim();log('COMMAND',`Phát lệnh “${c}” tới ${u}${n?`: ${n}`:''}`,u);save();$('#commandNote').value='';toast('Đã gửi lệnh',`${u} đã nhận “${c}”.`)};
$('#resetBtn').onclick=()=>{if(confirm('Khôi phục toàn bộ dữ liệu mẫu?')){data=structuredClone(SEED);save();toast('Đã khôi phục','Dữ liệu mẫu đã được nạp lại.')}};
$('#exportBtn').onclick=()=>{const rows=[['Thời gian','Loại','Nội dung','Tác nhân','Tham chiếu'],...data.logs.map(l=>[l.time,l.type,l.message,l.actor,l.ref])];const csv='\ufeff'+rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='utm-system-logs.csv';a.click();URL.revokeObjectURL(a.href);toast('Đã xuất CSV','Tệp nhật ký đã được tải xuống.')};
$('#addUavBtn').onclick=()=>toast('MVP giới hạn','Luồng thêm UAV sẽ được nối API ở phiên bản tiếp theo.');$$('.segmented button').forEach(b=>b.onclick=()=>{$$('.segmented button').forEach(x=>x.classList.remove('active'));b.classList.add('active');toast(b.textContent==='Mô phỏng'?'Chế độ mô phỏng':'Dữ liệu trực tiếp',b.textContent==='Mô phỏng'?'Hiển thị kế hoạch đã được duyệt.':'Đã trở lại luồng vận hành hiện tại.')});
setInterval(()=>{$('#clock').textContent=new Intl.DateTimeFormat('vi-VN',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZone:'Asia/Ho_Chi_Minh'}).format(new Date())},1000);renderAll();
